) AS v
WHERE NOT EXISTS (
  SELECT 1 FROM cabinet_dealz.crm_deals d
  WHERE d.affiliateId IS NULL
    AND (d.company LIKE 'Cabinet shop prospect%' OR d.notes LIKE '%cabinet_shop_list_%')
    AND (
      (LOWER(TRIM(d.contactName)) = LOWER(v.contactName) AND d.notes LIKE CONCAT('%State: ', v.state, '%'))
      OR (v.siteHost IS NOT NULL AND (d.notes LIKE CONCAT('%://', v.siteHost, '/%') OR d.notes LIKE CONCAT('%://www.', v.siteHost, '/%')))
    )
);

