  UNION ALL SELECT 'Cabinet shop prospect — Indian River Cabinet Design (Vero Beach, FL)' AS title, 'Indian River Cabinet Design' AS contactName, '(772) 413-1874' AS contactPhone, NULL AS contactEmail, 'Cabinet shop prospect' AS company, 'Vero Beach, FL' AS location, 'FL' AS state, 'indianrivercabinetdesign.com' AS siteHost, 'cabinet_shop_list_2026-11-24\nLocation: Vero Beach, FL | State: FL | Region: Treasure Coast\nAddress: 2112 5th Ave, Vero Beach, FL 32960\nBusiness type: showroom/dealer\nWebsite: http://indianrivercabinetdesign.com/\nPhone: (772) 413-1874\nGoogle rating: 5.0 (1 reviews)\nConfidence: high\nSource library doc: Cabinet Shops in Florida (affiliate library, built Nov 24, 2026)\nSource: prior sweep (Exa Places map listing)' AS notes
