  UNION ALL SELECT 'Cabinet shop prospect — Treasure Coast Kitchen Remodeling Solutions (Vero Beach, FL)' AS title, 'Treasure Coast Kitchen Remodeling Solutions' AS contactName, '(772) 281-5280' AS contactPhone, NULL AS contactEmail, 'Cabinet shop prospect' AS company, 'Vero Beach, FL' AS location, 'FL' AS state, 'kitchenremodel-verobeach.com' AS siteHost, 'cabinet_shop_list_2026-11-24\nLocation: Vero Beach, FL | State: FL | Region: Treasure Coast\nAddress: 1826 14th Ave, Vero Beach, FL 32960\nBusiness type: mixed\nWebsite: https://www.kitchenremodel-verobeach.com/\nPhone: (772) 281-5280\nConfidence: low\nSource library doc: Cabinet Shops in Florida (affiliate library, built Nov 24, 2026)\nSource: prior sweep (Exa Places map listing) (retail)' AS notes
) AS v
WHERE NOT EXISTS (
  SELECT 1 FROM cabinet_dealz.crm_deals d
  WHERE d.affiliateId IS NULL
    AND (d.company LIKE 'Cabinet shop prospect%' OR d.notes LIKE '%cabinet_shop_list_%')
    AND (
      (LOWER(TRIM(d.contactName)) = LOWER(v.contactName) AND d.notes LIKE CONCAT('%State: ', v.state, '%'))
      OR (v.siteHost IS NOT NULL AND (d.notes LIKE CONCAT('%://', v.siteHost, '/%') OR d.notes LIKE CONCAT('%://www.', v.siteHost, '/%')))
    )
);

-- Verify (read-only): rows from this list by state. Expected after the inserts: FL 928
-- (minus any shop that was already in the CRM).
SELECT LEFT(SUBSTRING_INDEX(notes, 'State: ', -1), 2) AS state, COUNT(*) AS shops,
       SUM(notes LIKE '%Website: http%') AS withWebsite, SUM(contactPhone IS NOT NULL) AS withPhone
FROM cabinet_dealz.crm_deals
WHERE affiliateId IS NULL AND notes LIKE '%cabinet_shop_list_2026-11-24%'
GROUP BY state;
